using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
/* every opening of a CHB wall gets its lintel from the lintel schedule as soon as it is placed (owner, 21 November 2026); the lintels
   are Miscellaneous Structures / Lintel Beam quantities (concrete, forms, rebar) and are listed in their own tab */
partial class ProgramOfWorksForm {
 CheckBox autoLintels;DataGridView lintelGrid;Label lintelNote,lintelSummary,chbLintelSummary;static readonly int[] LintelDias={10,12,16,20,25};
 static readonly string[] LintelHeaders={"Lintel","Opening","Wall","CHB","Clear opening m","Units","b x h mm","Bottom","Top","Mid","Ties 10 mm","Bearing each end mm","Length m","Jamb bars each side","Lateral brace","Concrete m3","Formworks m2","RSB 10 mm kg","RSB 12 mm kg","RSB 16 mm kg","RSB 20 mm kg","RSB 25 mm kg","RSB total kg","Status"};
 void AddOpeningLintelsTab(){TabPage misc;if(sheetPages==null||!sheetPages.TryGetValue("Miscellaneous Structures",out misc))return;var host=AllControls(misc).OfType<TabControl>().FirstOrDefault();if(host==null)return;
  var page=new TabPage("Lintels over Openings"){Padding=new Padding(14,10,14,14)};var top=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=true,Padding=new Padding(0,0,0,6)};
  autoLintels=new CheckBox{Text="Add a lintel over every opening of a CHB wall automatically",Checked=true,AutoSize=true,Margin=new Padding(3,8,12,3)};autoLintels.CheckedChanged+=(s,e)=>{if(extraReady&&!filling)Recalculate();};top.Controls.Add(autoLintels);
  lintelNote=new Label{Dock=DockStyle.Top,AutoSize=false,Height=58,ForeColor=PowTheme.Muted,Padding=new Padding(2,4,2,4),Text="Marks LB-4A to LB-6E from the Lintel Beam Design Calculation Report: chosen from the CHB thickness and the clear opening (between two ranges the larger mark). Valid for gravity load with at most 2.5 m of CHB wall above and no other load; openings over 6.00 m need their own design. Do not also enter these lintels in the Lintel Beam sheet. Concrete, rebar grades and cover follow the Lintel Beam settings."};
  lintelGrid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};foreach(var h in LintelHeaders)lintelGrid.Columns.Add(h,h);foreach(DataGridViewColumn c in lintelGrid.Columns)c.SortMode=DataGridViewColumnSortMode.NotSortable;
  lintelSummary=new Label{Dock=DockStyle.Top,AutoSize=false,Height=30,Font=ModernUi.Strong,ForeColor=PowTheme.Teal,TextAlign=ContentAlignment.MiddleLeft};
  page.Controls.Add(lintelGrid);page.Controls.Add(lintelSummary);page.Controls.Add(lintelNote);page.Controls.Add(top);
  TabPage chb;if(sheetPages.TryGetValue("CHB Estimate",out chb)){chbLintelSummary=new Label{Dock=DockStyle.Top,AutoSize=false,Height=30,Font=ModernUi.Strong,ForeColor=PowTheme.Teal,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(6,0,0,0)};chb.Controls.Add(chbLintelSummary);chb.Controls.SetChildIndex(chbLintelSummary,chb.Controls.Count-1);}var tabs0=host.TabPages.Cast<TabPage>().ToList();int at=tabs0.FindIndex(t=>t.Text.Contains("Lintel"));host.TabPages.Clear();for(int i=0;i<tabs0.Count;i++){host.TabPages.Add(tabs0[i]);if(i==at)host.TabPages.Add(page);}if(at<0)host.TabPages.Add(page);}
 static IEnumerable<Control> AllControls(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in AllControls(c))yield return d;}}
 void RecalculateOpeningLintels(){lintelResults.Clear();if(lintelGrid!=null)lintelGrid.Rows.Clear();if(autoLintels!=null&&!autoLintels.Checked){ShowLintelTotals();return;}LengthConfiguration cfg;try{cfg=ExtraConfiguration("Lintel Beam");}catch(Exception){ShowLintelTotals();return;}
  var walls=wallItems.Where(w=>w.Material=="CHB").ToDictionary(w=>w.Id.Trim(),StringComparer.OrdinalIgnoreCase);
  foreach(var o in wallOpenings){WallItem wall;if(o==null||o.Wall==null||!walls.TryGetValue(o.Wall.Trim(),out wall))continue;
   try{LintelMark mark;var q=LintelSchedule.Takeoff(o,wall,cfg,out mark);miscQuantities.Add(q);miscPlan.AddRange(CommercialBars.Allocate(new[]{q.Steel},cfg,miscStock));
    lintelResults.Add(q);if(lintelGrid!=null){var cells=new System.Collections.Generic.List<object>{mark.Mark,o.Id,wall.Id,mark.Chb+"\"",o.Width.ToString("0.00",CultureInfo.InvariantCulture),q.Quantity,mark.Width+" x "+mark.Depth,mark.Bottom,mark.Top,mark.Mid,mark.Ties,mark.Bearing,(o.Width+2*mark.Bearing/1000.0).ToString("0.00",CultureInfo.InvariantCulture),mark.JambBarsPerSide+"-12",mark.Brace==""?"-":"Wall bars 10 mm @ 800 (not included)",q.Concrete.ToString("0.000",CultureInfo.InvariantCulture),q.Forms.ToString("0.00",CultureInfo.InvariantCulture)};
     foreach(int d in LintelDias)cells.Add(Kg(q,d)>0?Kg(q,d).ToString("0.00",CultureInfo.InvariantCulture):"");cells.Add(q.Steel.Result.Total.ToString("0.00",CultureInfo.InvariantCulture));cells.Add(wall.ThicknessMm>150?"6\" marks used for a "+wall.ThicknessMm.ToString("0",CultureInfo.InvariantCulture)+" mm wall - check":"Estimated");lintelGrid.Rows.Add(cells.ToArray());}}
   catch(Exception ex){errors.Add("Lintel over "+o.Id+" in wall "+wall.Id+": "+ex.Message);if(lintelGrid!=null){var cells=new object[lintelGrid.Columns.Count];cells[0]="-";cells[1]=o.Id;cells[2]=wall.Id;cells[cells.Length-1]=ex.Message;lintelGrid.Rows.Add(cells);}}}
  ShowLintelTotals();}
 readonly System.Collections.Generic.List<MiscStructureQuantity> lintelResults=new System.Collections.Generic.List<MiscStructureQuantity>();
 static double Kg(MiscStructureQuantity q,int dia){return q.Steel.Result.Lines.Where(l=>l.Diameter==dia).Sum(l=>l.Kg);}
 /* totals at once (owner, 21 November 2026: "compute mo na agad yung concrete, RSB, formworks"): the 12 mm jamb bars are included,
    the lateral brace is the wall's own vertical reinforcement and is not added here */
 void ShowLintelTotals(){int n=lintelResults.Sum(q=>q.Quantity);double c=lintelResults.Sum(q=>q.Concrete),f=lintelResults.Sum(q=>q.Forms),kg=lintelResults.Sum(q=>q.Steel.Result.Total);
  string dias=string.Join(", ",LintelDias.Where(d=>lintelResults.Sum(q=>Kg(q,d))>0).Select(d=>d+" mm "+lintelResults.Sum(q=>Kg(q,d)).ToString("0.00",CultureInfo.InvariantCulture)+" kg"));
  string text=n==0?"No lintels: assign openings to CHB walls (Door & Window Schedule or the wall's openings).":"LINTELS OVER OPENINGS: "+n+" lintel"+(n==1?"":"s")+"  |  Concrete "+c.ToString("0.000",CultureInfo.InvariantCulture)+" m3  |  Formworks "+f.ToString("0.00",CultureInfo.InvariantCulture)+" m2  |  RSB "+kg.ToString("0.00",CultureInfo.InvariantCulture)+" kg ("+dias+"), 12 mm jamb bars included, lateral brace not included";
  if(lintelSummary!=null)lintelSummary.Text=text;if(chbLintelSummary!=null)chbLintelSummary.Text=autoLintels!=null&&!autoLintels.Checked?"Automatic lintels are off (Miscellaneous Structures > Lintels over Openings).":text;
  if(lintelGrid!=null&&n>0){var cells=new object[lintelGrid.Columns.Count];cells[0]="TOTAL";cells[5]=n;cells[15]=c.ToString("0.000",CultureInfo.InvariantCulture);cells[16]=f.ToString("0.00",CultureInfo.InvariantCulture);for(int k=0;k<LintelDias.Length;k++){double v=lintelResults.Sum(q=>Kg(q,LintelDias[k]));cells[17+k]=v>0?v.ToString("0.00",CultureInfo.InvariantCulture):"";}cells[22]=kg.ToString("0.00",CultureInfo.InvariantCulture);int r=lintelGrid.Rows.Add(cells);lintelGrid.Rows[r].DefaultCellStyle.Font=new Font(lintelGrid.Font,FontStyle.Bold);lintelGrid.Rows[r].DefaultCellStyle.BackColor=Color.FromArgb(236,243,239);}}
}
}
